import{_ as i,C as n,o as t,c as s,E as r,a2 as o}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"行业架构学术观察 001 — NIST AI RMF 定义的是治理运行循环，而不是检查清单","description":"","frontmatter":{"title":"行业架构学术观察 001 — NIST AI RMF 定义的是治理运行循环，而不是检查清单","date":"2026-08-02","column":"industry-architecture","category":"academic","summary":"NIST AI RMF 1.0 通过 Govern、Map、Measure 与 Manage 组织 AI 风险工作；要成为可执行系统，必须把这些 Function 转换为持久记录、证据、决策与反馈迁移。","sources":["NIST AI Risk Management Framework 1.0","NIST AI RMF Playbook","NIST AI 600-1 Generative AI Profile"],"outline":"deep","cover":"/assets/covers/nist-ai-rmf-operating-loop-cover-v2.jpg"},"headers":[],"relativePath":"zh/industry/2026-08-02-nist-ai-rmf-operating-loop.md","filePath":"zh/industry/2026-08-02-nist-ai-rmf-operating-loop.md","lastUpdated":1787407830000}'),l={name:"zh/industry/2026-08-02-nist-ai-rmf-operating-loop.md"};function c(p,e,d,h,m,u){const a=n("ArticleCover");return t(),s("div",null,[r(a,{image:"/assets/covers/nist-ai-rmf-operating-loop-cover-v2.jpg",kicker:"行业架构 · 学术观察 001",title:"NIST AI RMF 定义的是治理运行循环，而不是检查清单",summary:"Govern、Map、Measure 与 Manage 是贯穿 AI Lifecycle 的关联风险 Function；执行需要持久运营记录。",version:"IA001",status:"Production Test V1 · 2026-08-02",languageHref:"/en/industry/2026-08-02-nist-ai-rmf-operating-loop",languageLabel:"English"}),e[0]||(e[0]=o(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>NIST AI Risk Management Framework 1.0 是一套 Voluntary、Rights-preserving、Non-sector-specific、Use-case-agnostic Framework，旨在帮助组织贯穿 Design、Development、Deployment、Use 与 Evaluation 管理 AI Risk。</p><p>它的运营核心包含四个 Function：<strong>Govern、Map、Measure、Manage</strong>。Playbook 为四个 Function 补充 Suggested Action 与 Reference；NIST AI 600-1 则以 Cross-sectoral Profile 方式把 Framework 应用于 Generative AI Risk。</p><p>这一 Framework 经常被压缩成四个标题，或者被当成 Compliance Checklist。NIST 自身的描述指向另一个方向：这些 Function 具有 Contextual、Iterative 特征，并且可以贯穿 Lifecycle 使用。</p><p>Research Center 的判断是：</p><blockquote><p>只有当 Govern、Map、Measure 与 Manage 被表示成持久 Record、产生 Evidence 的 Activity、可问责 Decision 和 Feedback Transition 时，AI RMF 才能成为 Operating System。Framework 定义 Outcome，Implementation 必须补齐可执行机制。</p></blockquote><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="主要研究对象" tabindex="-1">主要研究对象 <a class="header-anchor" href="#主要研究对象" aria-label="Permalink to &quot;主要研究对象&quot;">​</a></h3><ol><li><strong>NIST AI 100-1, Artificial Intelligence Risk Management Framework (AI RMF 1.0)</strong>，2023 年 1 月 26 日发布。</li><li><strong>NIST AI RMF Playbook</strong>，为四个 Function 提供 Suggested Action 的配套资源。</li><li><strong>NIST AI 600-1, Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile</strong>，2024 年 7 月 26 日发布的 Generative AI Companion Profile。</li></ol><p>本笔记评估正式发布的 1.0 Framework 与 GenAI Profile。NIST 仍在维护和演进相关材料，因此任何架构 Decision 都应保留引用的精确 Version。</p><h3 id="research-question" tabindex="-1">Research Question <a class="header-anchor" href="#research-question" aria-label="Permalink to &quot;Research Question&quot;">​</a></h3><p>能否把 AI RMF Function 转换为 Digital Employee 与 Research Operating System 的具体运行架构，同时避免把 Framework 变成僵化或虚假的 Compliance Checklist？</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-govern-是跨越所有阶段的运行条件" tabindex="-1">1. Govern 是跨越所有阶段的运行条件 <a class="header-anchor" href="#_1-govern-是跨越所有阶段的运行条件" aria-label="Permalink to &quot;1. Govern 是跨越所有阶段的运行条件&quot;">​</a></h3><p>Govern 建立 Policy、Accountability、Culture、Role、Legal/Organizational Context、Documentation 与 Oversight。它并不是技术工作开始之前的一次性首阶段，而是影响所有后续 Decision，并从 Measurement 与 Management 中接收反馈。</p><p>对于 Operating System，Govern 意味着任何工作都不能缺少 Accountable Owner、Authority Model、Policy Basis、Lifecycle 与 Escalation Route。</p><h3 id="_2-map-在解释-risk-之前建立-context" tabindex="-1">2. Map 在解释 Risk 之前建立 Context <a class="header-anchor" href="#_2-map-在解释-risk-之前建立-context" aria-label="Permalink to &quot;2. Map 在解释 Risk 之前建立 Context&quot;">​</a></h3><p>Map 识别 AI System 的 Intended Purpose、Stakeholder、Impact、Operating Environment、Dependency、Limitation 与 Risk Context。</p><p>缺少 Context 的 Risk Statement 并不完整。同一种 Capability 在 Sandboxed Research Task 中可能可以接受，但在 Employment、Financial、Medical 或 Irreversible Operational Decision 中可能不可接受。</p><h3 id="_3-measure-把-claim-连接到-evidence" tabindex="-1">3. Measure 把 Claim 连接到 Evidence <a class="header-anchor" href="#_3-measure-把-claim-连接到-evidence" aria-label="Permalink to &quot;3. Measure 把 Claim 连接到 Evidence&quot;">​</a></h3><p>Measure 评估已识别 Risk、Trustworthiness Characteristic、Performance、Uncertainty、Limitation 与 Monitoring Signal。它依赖适合已映射 Context 的 Method 与 Metric。</p><p>Framework 并不提供一个 Universal Score。Measurement 应产生支持有边界 Decision 的 Evidence，而不是装饰性 Dashboard。</p><h3 id="_4-manage-把-evidence-转换为优先行动" tabindex="-1">4. Manage 把 Evidence 转换为优先行动 <a class="header-anchor" href="#_4-manage-把-evidence-转换为优先行动" aria-label="Permalink to &quot;4. Manage 把 Evidence 转换为优先行动&quot;">​</a></h3><p>Manage 对 Risk 排序，选择 Response，分配 Resource，监控 Outcome，沟通 Residual Risk，并决定 System 是否继续、修改、暂停或退役。</p><p>如果一次 Measurement 没有改变 Decision、Control、Work Item 或 Monitoring Obligation，那么 Operating Loop 尚未完成。</p><h3 id="_5-四个-function-相互连接-而不是顺序方框" tabindex="-1">5. 四个 Function 相互连接，而不是顺序方框 <a class="header-anchor" href="#_5-四个-function-相互连接-而不是顺序方框" aria-label="Permalink to &quot;5. 四个 Function 相互连接，而不是顺序方框&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 ┌──────────────┐</span></span>
<span class="line"><span>                 │    GOVERN    │</span></span>
<span class="line"><span>                 │ Policy, Role │</span></span>
<span class="line"><span>                 │Accountability│</span></span>
<span class="line"><span>                 └──────┬───────┘</span></span>
<span class="line"><span>                        │ shapes all</span></span>
<span class="line"><span>           ┌────────────┼────────────┐</span></span>
<span class="line"><span>           ▼            ▼            ▼</span></span>
<span class="line"><span>        MAP ─────────▶ MEASURE ─────────▶ MANAGE</span></span>
<span class="line"><span>      Context             Evidence          Action</span></span>
<span class="line"><span>        ▲                                     │</span></span>
<span class="line"><span>        └──────── Feedback and changed context┘</span></span></code></pre></div><p><em>图：joinwell52 Research Center 根据 NIST AI RMF 1.0 与 Playbook 综合。</em></p><p>Manage Action 会改变 System 或 Environment，从而要求重新 Map 与 Measure。Governance 则从 Incident、Monitoring 与 Stakeholder Feedback 中吸收经验。</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="从-framework-outcome-到-executable-record" tabindex="-1">从 Framework Outcome 到 Executable Record <a class="header-anchor" href="#从-framework-outcome-到-executable-record" aria-label="Permalink to &quot;从 Framework Outcome 到 Executable Record&quot;">​</a></h3><p>Software Implementation 需要为每个 Function 建立显式 Artifact：</p><table tabindex="0"><thead><tr><th>RMF Function</th><th>必须存在的运行记录</th><th>示例 Gate 或 Event</th></tr></thead><tbody><tr><td>Govern</td><td>Owner、Position、Authority、Policy、Lifecycle、Accountability、Exception Route</td><td>因 Owner 或 Authority 缺失而拒绝 Admission</td></tr><tr><td>Map</td><td>Purpose、Stakeholder、Environment、Dependency、Data、Impact、Limitation、Misuse Context</td><td>Task 被归为 High-impact 或超出 Approved Purpose</td></tr><tr><td>Measure</td><td>Test Plan、Benchmark Version、Evidence、Uncertainty、Monitoring Signal、Evaluator Result</td><td>Evidence Gate 失败或 Confidence 不足</td></tr><tr><td>Manage</td><td>Risk Decision、Treatment、Approver、Residual Risk、Action Owner、Review Date</td><td>Release、Restrict、Remediate、Pause、Escalate、Retire</td></tr></tbody></table><p><em>表：joinwell52 Research Center 综合。</em></p><p>关键工程规则是：每个 Decision 都必须引用当时使用的 Context 与 Evidence。否则组织无法解释为什么同一 System 在某一场景获批，而在另一场景被阻止。</p><h3 id="govern-不应退化成一份中央文档" tabindex="-1">Govern 不应退化成一份中央文档 <a class="header-anchor" href="#govern-不应退化成一份中央文档" aria-label="Permalink to &quot;Govern 不应退化成一份中央文档&quot;">​</a></h3><p>存放在 PDF 中的 Governance Policy 是必要的，但并不充分。Runtime Governance 应把适用 Policy 投影到正在执行的工作：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">governance_context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  system_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  position_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  accountable_owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  intended_use_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority_snapshot_ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  applicable_policy_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  risk_tier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  required_evidence_refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  human_decision_points</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  prohibited_actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  exception_route</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>即使底层 Policy 后续改变，这个 Projection 也应针对当前 Run Versioned 且 Immutable。</p><h3 id="map-阻止泛化的-safe-agent-声明" tabindex="-1">Map 阻止泛化的“Safe Agent”声明 <a class="header-anchor" href="#map-阻止泛化的-safe-agent-声明" aria-label="Permalink to &quot;Map 阻止泛化的“Safe Agent”声明&quot;">​</a></h3><p>脱离 Context，不存在一个简单的 Safe 或 Unsafe Agent。Map 强迫 System 说明谁会受到影响、涉及什么 Decision 或 Action、使用什么 Data、Agent 在哪里运行、有哪些 Alternative，以及 Failure 意味着什么。</p><p>对数字员工而言，应在两个层次 Map：</p><ul><li><strong>Position Mapping</strong>：持久 Organizational Role 与常规 Authority。</li><li><strong>WorkOrder Mapping</strong>：具体 Task、Data、Stakeholder、Side Effect 与 Exception Condition。</li></ul><h3 id="measure-必须分开不同维度" tabindex="-1">Measure 必须分开不同维度 <a class="header-anchor" href="#measure-必须分开不同维度" aria-label="Permalink to &quot;Measure 必须分开不同维度&quot;">​</a></h3><p>Task Success、Security、Privacy、Fairness、Reliability、Transparency、Cost 与 Evidence Completeness 是不同维度。把它们合并成一个 Score，可能隐藏不可接受的 Failure。</p><p>Production Gate 应按维度定义 Minimum Condition，并允许记录 <code>not measured</code>，而不是虚构精度。</p><h3 id="manage-需要权威与后续闭环" tabindex="-1">Manage 需要权威与后续闭环 <a class="header-anchor" href="#manage-需要权威与后续闭环" aria-label="Permalink to &quot;Manage 需要权威与后续闭环&quot;">​</a></h3><p>写完 Analysis Report 并不代表 Risk Management 完成。Decision 必须确定：</p><ul><li>Authorized Decision Maker；</li><li>Selected Treatment；</li><li>Accepted Residual Risk；</li><li>Implementation Owner；</li><li>Deadline 或 Review Condition；</li><li>Monitoring 与 Escalation Path；</li><li>关闭 Action 所需 Evidence。</li></ul><p>这更像一个受治理 WorkOrder，而不是一页静态 Policy。</p><h3 id="genai-profile-增加-risk-detail-而不是建立另一套-operating-system" tabindex="-1">GenAI Profile 增加 Risk Detail，而不是建立另一套 Operating System <a class="header-anchor" href="#genai-profile-增加-risk-detail-而不是建立另一套-operating-system" aria-label="Permalink to &quot;GenAI Profile 增加 Risk Detail，而不是建立另一套 Operating System&quot;">​</a></h3><p>NIST AI 600-1 为 Framework 增加 Generative-AI-specific Risk 与 Action。从架构上看，它应作为 Profile 丰富 Map、Measure 与 Manage Requirement，同时继续运行在同一 Governance Loop 下。</p><p>System 可能需要按 Sector 或 Use Case 使用多个 Profile。Core Record 应保持稳定，而 Profile-specific Control 与 Evidence Requirement 可以变化。</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ol><li>AI RMF 是 Voluntary Framework，本身不构成 Legal Compliance 或 Certification。</li><li>它有意保持 Flexible，组织必须自行设计具体 Method、Threshold 与 Control。</li><li>四个 Function 不提供完整 Software Architecture 或 Data Model。</li><li>Contextual Implementation 会产生差异，两个组织可能都声称 Alignment，但实际运行方式完全不同。</li><li>如果 Decision、Evidence 与 Runtime Behavior 没有关联，Framework 可能只被仪式化执行。</li></ol><p>这些并非 General Framework 的缺陷，但它们界定了 Implementation 必须完成的工作。</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>本笔记不直接修改 TMPA 正式出版物。它支持 Governance、Context、Measurement、Decision、Action、Lifecycle 与 Evidence 之间的显式 Reference。确定性重建必须显示每次 Management Decision 由哪一份 Mapped Context 与 Measured Evidence 支持。</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>数字员工 Governance 应实现为持续运行循环：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Position and Policy</span></span>
<span class="line"><span>→ WorkOrder Context Mapping</span></span>
<span class="line"><span>→ Runtime and Outcome Measurement</span></span>
<span class="line"><span>→ Risk and Completion Decision</span></span>
<span class="line"><span>→ Remediation, Restriction, Release, or Retirement</span></span>
<span class="line"><span>→ Feedback to Position, Policy, and future WorkOrders</span></span></code></pre></div><p>Control Plane 应维护 Fleet-level Govern 与 Map Record；Work Runtime 应产生 Measure Evidence；Authorized Human 或受治理 Decision Rule 执行 Manage Transition。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu 应增加轻量 AI RMF Projection，而不是先建设大型 Compliance Subsystem。最小实现可以包括：</p><ol><li><code>governance-context.yaml</code>：Owner、Position、Authority、Policy 与 Prohibited Action；</li><li>WorkOrder Risk/Context Block；</li><li>Report 中的 Evidence 与 Evaluator Reference；</li><li>显式 Release、Restrict、Remediate、Escalate 与 Retire Decision；</li><li>产生新 Task 或更新 Position Policy 的 Feedback Record。</li></ol><p>只要关系显式且 Machine-readable，现有 FCoP Lifecycle、Report、EVAL、QA 与 ADMIN Authority 已经可以提供大量执行结构。</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>把当前 Research OS 与 CodeFlowMu Artifact 映射到 Govern、Map、Measure 与 Manage。</li><li>定义最小 Machine-readable AI RMF Projection。</li><li>建立一个 Position-level 与一个 WorkOrder-level Mapping Example。</li><li>分开 Operational Evidence 与 Policy Assertion。</li><li>测试 GenAI Profile Requirement 如何改变 Computer-use Digital Employee Workflow。</li><li>定义 Risk Acceptance、Expiration、Review 与 Retirement Transition。</li><li>跟踪未来 NIST Revision，同时不覆盖 1.0 Evidence Baseline。</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>NIST，<strong>Artificial Intelligence Risk Management Framework (AI RMF 1.0), NIST AI 100-1</strong>：<a href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10" target="_blank" rel="noreferrer">https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10</a></li><li>NIST，<strong>AI Risk Management Framework</strong>：<a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework</a></li><li>NIST，<strong>AI RMF Playbook</strong>：<a href="https://www.nist.gov/itl/ai-risk-management-framework/nist-ai-rmf-playbook" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework/nist-ai-rmf-playbook</a></li><li>NIST，<strong>Artificial Intelligence Risk Management Framework: Generative Artificial Intelligence Profile, NIST AI 600-1</strong>：<a href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-generative-artificial-intelligence" target="_blank" rel="noreferrer">https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-generative-artificial-intelligence</a></li></ol>`,71))])}const f=i(l,[["render",c]]);export{g as __pageData,f as default};
